css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .62); position: relative; }
.loader::before { content: ''; position: absolute; left: 5%; top: 66%; width: 90%; height: 5%; border-radius: 999px; background: var(--accent-2); }
.loader::after { content: ''; position: absolute; left: 22%; top: 20%; width: 52%; height: 50%; border: calc(var(--loader-size) * .042) solid var(--accent); border-bottom: 0; border-radius: 50% 50% 0 0 / 100% 100% 0 0; }
.loader span { position: absolute; width: 12%; height: calc(var(--loader-size) * .12); border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 calc(var(--loader-size) * .022) color-mix(in srgb, #fff 70%, var(--accent)); animation: commit calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
.loader span:nth-child(1) { left: 6%; top: 60%; background: var(--accent-2); }
.loader span:nth-child(2) { left: 44%; top: 8%; animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-child(3) { left: 82%; top: 60%; background: var(--accent-2); animation-delay: calc(var(--loader-speed) * 1.2); }
@keyframes commit { 0%, 100% { opacity: .28; transform: scale(.6); } 45% { opacity: 1; transform: scale(1); } }
